//! The canonical venue a publication source's venue string names. Lattice has
//! one venue vocabulary: `src/papers/venues.ts`, generated by
//! `scripts/gen-venues.mjs` from bibcite's table plus Lattice's overlay, which
//! Add papers and the entry editor offer as suggestions. The audit proposes
//! those same names, so a source's spelling of a venue the entry already
//! cites ("Advances in Neural Information Processing Systems 35", "Proceedings
//! of the 19th Conference of the {E}uropean Chapter ... (Volume 1: Long
//! Papers)") is not a correction.
//!
//! Matching is by equality of a normalized key, never containment or an
//! acronym embedded in a longer string: bibcite's looser matching collapses
//! "Findings of the ACL: EMNLP 2026" into EMNLP, and a wrong canonical name is
//! worse than keeping the source's own string.
use super::*;
use std::collections::HashMap;
use std::sync::LazyLock;
use unicode_normalization::{char::is_combining_mark, UnicodeNormalization};

const VENUES_TS: &str = include_str!("../../../src/papers/venues.ts");

/// Venues named by year (bibcite's year rules): (older name, newer name,
/// first year of the newer name).
const YEAR_RENAMES: [(&str, &str, u32); 2] = [
    (
        "Advances in Neural Information Processing Systems (NIPS)",
        "Advances in Neural Information Processing Systems (NeurIPS)",
        2018,
    ),
    (
        "IEEE Workshop on Applications of Computer Vision (WACV)",
        "IEEE/CVF Winter Conference on Applications of Computer Vision (WACV)",
        2017,
    ),
];

/// Words that do not distinguish venues: publisher prefixes, "Proceedings of
/// the", and the ordinals and numbers of one edition ("19th", "Thirty-Sixth",
/// "35", "2026").
const NOISE: [&str; 13] = [
    "ieee",
    "cvf",
    "acm",
    "rsj",
    "the",
    "annual",
    "proceedings",
    "proc",
    "of",
    "on",
    "in",
    "a",
    "an",
];
const NUMBER_WORDS: [&str; 34] = [
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
    "tenth",
    "eleventh",
    "twelfth",
    "thirteenth",
    "fourteenth",
    "fifteenth",
    "sixteenth",
    "seventeenth",
    "eighteenth",
    "nineteenth",
    "twentieth",
    "thirtieth",
    "fortieth",
    "fiftieth",
    "sixtieth",
    "seventieth",
    "twenty",
    "thirty",
    "forty",
    "fifty",
    "sixty",
    "seventy",
    "eighty",
    "ninety",
    "hundredth",
];

/// Each canonical name by its whole key, so a parenthetical that tells venues
/// apart ("ACM Transactions on Graphics (Proceedings of ACM SIGGRAPH Asia)")
/// still finds that one venue.
static WHOLE: LazyLock<HashMap<String, Vec<&'static str>>> =
    LazyLock::new(|| index(names().map(|name| (key(name, true), name))));

/// Each canonical name by its key without parentheticals, and by each
/// parenthetical alone (its acronym, "Findings of EMNLP").
static CORE: LazyLock<HashMap<String, Vec<&'static str>>> = LazyLock::new(|| {
    index(names().flat_map(|name| {
        let parentheticals = PARENTHETICAL
            .find_iter(name)
            .map(move |m| (key(&name[m.start() + 1..m.end() - 1], false), name));
        std::iter::once((key(name, false), name)).chain(parentheticals)
    }))
});

fn index(
    pairs: impl Iterator<Item = (String, &'static str)>,
) -> HashMap<String, Vec<&'static str>> {
    let mut index: HashMap<String, Vec<&'static str>> = HashMap::new();
    for (key, name) in pairs.filter(|(key, _)| !key.is_empty()) {
        let names = index.entry(key).or_default();
        if !names.contains(&name) {
            names.push(name);
        }
    }
    index
}

static PARENTHETICAL: LazyLock<regex::Regex> =
    LazyLock::new(|| regex::Regex::new(r"\([^()]*\)").unwrap());

/// Every venue name in the generated vocabulary.
fn names() -> impl Iterator<Item = &'static str> {
    static NAME: LazyLock<regex::Regex> =
        LazyLock::new(|| regex::Regex::new(r#"\{ name: ("(?:[^"\\]|\\.)*")"#).unwrap());
    NAME.captures_iter(VENUES_TS).map(|captures| {
        let literal = captures.get(1).unwrap().as_str();
        // JSON.stringify wrote the literal; only an escaped name needs decoding.
        if literal.contains('\\') {
            let decoded: String = serde_json::from_str(literal).expect("venues.ts name literal");
            &*Box::leak(decoded.into_boxed_str())
        } else {
            &literal[1..literal.len() - 1]
        }
    })
}

/// The words that identify a venue: TeX braces and escapes, accents, case and
/// `NOISE` removed, and unless `parentheticals`, parenthetical asides too
/// (acronyms, "(Volume 1: Long Papers)").
fn key(venue: &str, parentheticals: bool) -> String {
    let plain: String = venue
        .replace(['{', '}'], "")
        .replace('\\', "")
        .nfd()
        .filter(|c| !is_combining_mark(*c))
        .collect::<String>()
        .to_lowercase()
        .replace('&', " and ");
    let plain = if parentheticals { plain.into() } else { PARENTHETICAL.replace_all(&plain, " ") };
    let words = plain
        .split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|word| {
            !word.is_empty()
                && !NUMBER_WORDS.contains(word)
                && !word.chars().all(|c| c.is_ascii_digit())
                && !is_numeric_ordinal(word)
        })
        .collect::<Vec<_>>();
    let distinctive =
        words.iter().filter(|word| !NOISE.contains(word)).copied().collect::<Vec<_>>();
    // A name made only of `NOISE` ("Proceedings of the IEEE") is its own key.
    if distinctive.is_empty() { words } else { distinctive }.join(" ")
}

fn is_numeric_ordinal(word: &str) -> bool {
    ["st", "nd", "rd", "th"].iter().any(|suffix| {
        word.strip_suffix(suffix)
            .is_some_and(|digits| !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()))
    })
}

/// The canonical names `venue` may refer to: the one its whole spelling
/// names, else every name sharing its key.
fn candidates(venue: &str) -> &'static [&'static str] {
    WHOLE
        .get(&key(venue, true))
        .filter(|names| names.len() == 1)
        .or_else(|| CORE.get(&key(venue, false)))
        .map_or(&[], Vec::as_slice)
}

/// `name` as it is called in `year`.
fn in_year(name: &'static str, year: Option<u32>) -> &'static str {
    match YEAR_RENAMES.iter().find(|(old, new, _)| name == *old || name == *new) {
        Some((old, new, first)) => match year {
            Some(year) if year < *first => old,
            _ => new,
        },
        None => name,
    }
}

/// The canonical name `venue` refers to in `year`, or None when it names no
/// canonical venue or several unrelated ones.
pub(super) fn canonical_venue(venue: &str, year: Option<u32>) -> Option<&'static str> {
    let mut names = candidates(venue).iter().map(|name| in_year(name, year)).collect::<Vec<_>>();
    names.dedup();
    match names.as_slice() {
        [name] => Some(name),
        // A bare journal name shared by its special issues ("ACM Transactions
        // on Graphics" and its SIGGRAPH proceedings) is the journal itself:
        // the one named only by an acronym.
        _ => {
            let mut plain = names.into_iter().filter(|name| {
                PARENTHETICAL.find_iter(name).all(|m| !name[m.start()..m.end()].contains(' '))
            });
            plain.next().filter(|_| plain.next().is_none())
        }
    }
}

/// Whether `remote` names the venue `local` cites: the same canonical venue,
/// or a shared spelling that could be it ("ACM Transactions on Graphics" for
/// "ACM Transactions on Graphics (Proceedings of ACM SIGGRAPH)").
pub(super) fn same_canonical_venue(local: &str, remote: &str, year: Option<u32>) -> bool {
    canonical_venue(local, year)
        .is_some_and(|local| candidates(remote).iter().any(|name| in_year(name, year) == local))
}

/// `entry` with a journal or booktitle that names a canonical venue written
/// by that name, so an import stores the venue as Add papers suggests it
/// ("Proceedings of the 18th Conference of the {E}uropean Chapter ..." as
/// "... (EACL)"). Check citations treats either spelling as the same venue.
pub(super) fn canonical_venues(entry: &str) -> String {
    let values = fields(entry);
    let year = field_value(&values, "year").parse().ok();
    let mut expressions = field_expressions(entry);
    let mut changed = false;
    for name in ["journal", "booktitle"] {
        let Some(canonical) = values.get(name).and_then(|venue| canonical_venue(venue, year))
        else {
            continue;
        };
        if values[name] != canonical {
            expressions.insert(name.into(), format!("{{{canonical}}}"));
            changed = true;
        }
    }
    let spans = project::bibliography_entry_spans(entry);
    match spans.first().filter(|_| changed && spans.len() == 1) {
        Some((key, _, _)) if values.keys().all(|key| expressions.contains_key(key)) => {
            render_entry(&entry_type(entry), key, expressions)
        }
        _ => entry.to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const NEURIPS: &str = "Advances in Neural Information Processing Systems (NeurIPS)";
    const ICCV: &str = "IEEE/CVF International Conference on Computer Vision (ICCV)";
    const EACL: &str = "Proceedings of the Conference of the European Chapter of the Association for Computational Linguistics (EACL)";
    const FINDINGS_EMNLP: &str =
        "Findings of the Association for Computational Linguistics: EMNLP (Findings of EMNLP)";

    #[test]
    fn source_spellings_name_the_canonical_venue() {
        for (venue, year, canonical) in [
            ("Advances in Neural Information Processing Systems 35", 2022, NEURIPS),
            ("Advances in Neural Information Processing Systems (NeurIPS)", 2022, NEURIPS),
            ("NeurIPS 2022", 2022, NEURIPS),
            (
                "Advances in Neural Information Processing Systems 30",
                2017,
                "Advances in Neural Information Processing Systems (NIPS)",
            ),
            ("Proceedings of the IEEE/CVF International Conference on Computer Vision (ICCV)", 2023, ICCV),
            ("2023 IEEE/CVF International Conference on Computer Vision (ICCV)", 2023, ICCV),
            ("ICCV", 2023, ICCV),
            (
                "Proceedings of the 19th Conference of the {E}uropean Chapter of the {A}ssociation for {C}omputational {L}inguistics (Volume 1: Long Papers)",
                2026,
                EACL,
            ),
            (EACL, 2026, EACL),
            ("Findings of the Association for Computational Linguistics: EMNLP 2026", 2026, FINDINGS_EMNLP),
            ("Findings of EMNLP", 2026, FINDINGS_EMNLP),
            (FINDINGS_EMNLP, 2026, FINDINGS_EMNLP),
            (
                "Findings of the Association for Computational Linguistics: ACL 2023",
                2023,
                "Findings of the Association for Computational Linguistics: ACL (Findings of ACL)",
            ),
            (
                "Proceedings of the Thirty-Sixth Conference on Neural Information Processing Systems",
                2022,
                // "Conference on Neural Information Processing Systems" is not
                // a canonical spelling; no guess is better than a wrong one.
                "",
            ),
        ] {
            let found = canonical_venue(venue, Some(year)).unwrap_or("");
            assert_eq!(found, canonical, "{venue}");
        }
    }

    #[test]
    fn findings_and_main_conferences_stay_distinct() {
        let emnlp = "Proceedings of the Conference on Empirical Methods in Natural Language Processing (EMNLP)";
        assert_eq!(canonical_venue("EMNLP", Some(2026)), Some(emnlp));
        assert_eq!(
            canonical_venue(
                "Proceedings of the 2026 Conference on Empirical Methods in Natural Language Processing",
                Some(2026)
            ),
            Some(emnlp)
        );
        assert_ne!(canonical_venue("Findings of EMNLP", Some(2026)), Some(emnlp));
        // A string that only contains a venue's acronym is not that venue.
        assert_eq!(canonical_venue("Workshop at EMNLP 2026", Some(2026)), None);
        assert_eq!(canonical_venue("arXiv preprint arXiv:2401.12345", Some(2024)), None);
    }

    #[test]
    fn every_canonical_name_maps_to_itself() {
        let names = names().collect::<Vec<_>>();
        assert!(names.len() > 170 && names.contains(&FINDINGS_EMNLP), "{}", names.len());
        for name in names {
            let year = YEAR_RENAMES
                .iter()
                .find_map(|(old, _, first)| (name == *old).then_some(first - 1))
                .unwrap_or(2026);
            assert_eq!(canonical_venue(name, Some(year)), Some(name), "{name}");
        }
    }

    /// The captain's native-VLM bibliography: a source's spelling of the venue
    /// an entry already cites is no proposal, and a genuine correction is
    /// proposed by its canonical name.
    #[test]
    fn a_restated_venue_is_no_change_and_a_corrected_one_is_canonical() {
        use super::super::*;
        let entry = |venue: &str| {
            format!("@inproceedings{{alayrac2022flamingo, title={{Flamingo: A Visual Language Model for Few-Shot Learning}}, author={{Alayrac, Jean-Baptiste and Donahue, Jeff}}, booktitle={{{venue}}}, year={{2026}}, pages={{1--10}}}}")
        };
        let neurips = entry("Advances in Neural Information Processing Systems (NeurIPS)")
            .replace("2026", "2022");
        for (local, remote) in [
            (neurips.clone(), neurips.replace("(NeurIPS)", "35")),
            (entry(ICCV), entry("Proceedings of the IEEE/CVF International Conference on Computer Vision (ICCV)")),
            (entry(EACL), entry("Proceedings of the 19th Conference of the {E}uropean Chapter of the {A}ssociation for {C}omputational {L}inguistics (Volume 1: Long Papers)")),
            (
                entry("Findings of the Association for Computational Linguistics: EMNLP 2026"),
                entry("Findings of the Association for Computational Linguistics: EMNLP 2026"),
            ),
            (entry(FINDINGS_EMNLP), entry("Findings of the Association for Computational Linguistics: EMNLP 2026")),
            (entry("Findings of EMNLP"), entry("Findings of the Association for Computational Linguistics: EMNLP 2026")),
            (entry("NeurIPS"), entry("Advances in Neural Information Processing Systems 39")),
        ] {
            let checked = compare_title_entry(&local, &remote);
            assert!(checked.verified(), "{remote}");
            assert!(
                !checked.changes.iter().any(|change| change.field == "booktitle"),
                "{local}\n{remote}\n{:?}",
                checked.after
            );
        }
        for (local, remote, canonical) in [
            (
                "EMNLP",
                "Findings of the Association for Computational Linguistics: EMNLP 2026",
                FINDINGS_EMNLP,
            ),
            ("ICLR", "ICML 2026", "International Conference on Machine Learning (ICML)"),
            (
                "arXiv preprint arXiv:2204.14198",
                "Advances in Neural Information Processing Systems 39",
                NEURIPS,
            ),
        ] {
            let after = compare_title_entry(&entry(local), &entry(remote)).after.unwrap();
            assert_eq!(fields(&after)["booktitle"], canonical, "{remote}");
        }
    }
}
